/// Merges two already-sorted ascending vectors into a single sorted vector.
/// Duplicates from both inputs are kept (so [1,2] + [2,3] -> [1,2,2,3]).
pub fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_merge_empty() {
        assert_eq!(merge_sorted(&[], &[]), vec![]);
    }

    #[test]
    fn test_merge_one_empty_one_not() {
        assert_eq!(merge_sorted(&[], &[1]), vec![1]);
        assert_eq!(merge_sorted(&[5], &[]), vec![5]);
    }

    #[test]
    fn test_merge_equal_length() {
        assert_eq!(merge_sorted(&[1, 2, 3], &[3, 4, 5]), vec![1, 2, 3, 3, 4, 5]);
    }

    #[test]
    fn test_merge_different_lengths() {
        assert_eq!(
            merge_sorted(&[1, 2, 3], &[4, 5, 6, 7]),
            vec![1, 2, 3, 4, 5, 6, 7]
        );
    }

    #[test]
    fn test_merge_duplicates() {
        assert_eq!(
            merge_sorted(&[1, 2, 2, 3], &[2, 3, 4, 4]),
            vec![1, 2, 2, 2, 3, 3, 4, 4]
        );
    }
}

fn main() {
    let m = merge_sorted(&[1, 4, 7], &[2, 3, 8]);
    println!("{:?}", m);
}
