use std::collections::HashMap;

/// Parses a string like "foo=bar, baz= qux " into a HashMap.
/// Whitespace around keys and values is trimmed.
/// Returns Err if any pair is missing `=`.
pub fn parse_kv(s: &str) -> Result<HashMap<String, String>, String> {
    let mut out = HashMap::new();
    if s.trim().is_empty() {
        return Ok(out);
    }
    for pair in s.split(',') {
        let pair = pair.trim();
        let (k, v) = pair.split_once('=').ok_or_else(|| format!("missing '=' in pair: {}", pair))?;
        out.insert(k.trim().to_string(), v.trim().to_string());
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_pair() {
        assert_eq!(
            parse_kv("foo=bar"),
            Ok(vec!["foo".to_string(), "bar".to_string()].into_iter().collect())
        );
    }

    #[test]
    fn test_multiple_pairs() {
        assert_eq!(
            parse_kv("foo=bar, baz=qux"),
            Ok(vec![
                "foo".to_string(),
                "bar".to_string(),
                "baz".to_string(),
                "qux".to_string()
            ]
            .into_iter()
            .collect())
        );
    }

    #[test]
    fn test_whitespace_around_keys_values() {
        assert_eq!(
            parse_kv("  foo   =     bar  "),
            Ok(vec!["foo".to_string(), "bar".to_string()].into_iter().collect())
        );
    }

    #[test]
    fn test_empty_input() {
        assert!(parse_kv("").is_ok());
    }

    #[test]
    fn test_missing_equals() {
        assert!(parse_kv("noequals").is_err());
    }
}
